public class Solution {
    public String fizzBuzz(int n) {
        String r = "";
        for (int i = 1; i <= n; i++) {
            // String concat в цикле — O(n^2)
            if (i > 1) r = r + "\n";
            if (i % 15 == 0) r = r + "FizzBuzz";
            else if (i % 3 == 0) r = r + "Fizz";
            else if (i % 5 == 0) r = r + "Buzz";
            else r = r + i;
        }
        return r;
    }
}
